import { getImageProps } from "next/image";

const PRODUCT_FILM_POSTER_BLUR = {
  dark: "data:image/jpeg;base64,",
  light:
    "data:image/jpeg;base64,",
} as const;

export function filmPosterImageProps(src: string, theme: keyof typeof PRODUCT_FILM_POSTER_BLUR) {
  return getImageProps({
    alt: "",
    blurDataURL: PRODUCT_FILM_POSTER_BLUR[theme],
    height: 338,
    placeholder: "blur",
    src,
    width: 600,
  }).props;
}
